import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    urls = re.findall(r'https?://[^\s]+', myString)
    domains = {urllib.parse.urlparse(url).netloc for url in urls if urllib.parse.urlparse(url).netloc}

    geolocation_results = {}
    for domain in domains:
        try:
            api_url = f"http://ip-api.com/json/{domain}?key={API_KEY}"
            response = requests.get(api_url)
            if response.status_code == 200:
                geolocation_results[domain] = response.json()
            else:
                geolocation_results[domain] = None
        except Exception:
            geolocation_results[domain] = None

    return geolocation_results

